import Image from "next/image";

/**
 * Claude brand mark — the owner-provided Anthropic sunburst asset
 * (`/public/logos/claude.png`), shown wherever we surface the Claude AI Builder
 * integration. Single source of truth so the mark is identical everywhere;
 * nominative use of a third-party brand to indicate a real integration.
 */
export function ClaudeMark({ size = 22, className }: { size?: number; className?: string }) {
  return (
    <Image
      src="/logos/claude.png"
      alt="Claude"
      width={size}
      height={size}
      className={className}
      style={{ width: size, height: size }}
    />
  );
}

