function ClaudeGlyph({ className = "" }: { className?: string }) {
  // Anthropic "sunburst" mark, in Claude's clay color.
  return (
    <svg viewBox="0 0 40 40" className={className} aria-hidden fill="#D97757">
      {Array.from({ length: 12 }).map((_, i) => {
        const a = (i * Math.PI) / 6;
        const x1 = 20 + Math.cos(a) * 6;
        const y1 = 20 + Math.sin(a) * 6;
        const x2 = 20 + Math.cos(a) * 17;
        const y2 = 20 + Math.sin(a) * 17;
        return <line key={i} x1={x1} y1={y1} x2={x2} y2={y2} stroke="#D97757" strokeWidth="3.4" strokeLinecap="round" />;
      })}
    </svg>
  );
}

